 if(!leaf([field.key,'url'],canonical))return;const expected=lastCommitted,page=props.pageId,published=props.pagePublished,receipt=receiptEpoch;await nextTick();if(editable()&&canChooseMedia.value&&receiptEpoch===receipt&&actor()===issued.actor&&props.editorKey===issued.editor&&selected.value===issued.index&&props.pageId===page&&props.pagePublished===published&&props.modelValue===expected&&block.value&&canonicalPresentationReference(text(read(block.value,[field.key,'url'])))===canonical)capabilities.value=[{...seckillImageScope(block.value,field.key),preview:approved}];
